      const steps = [
        bi(`site = (word & ${2 ** s.id_bits - 1}) − 1 = ${(r.w[0] & (2 ** s.id_bits - 1))} − 1 = <b>${r.site}</b>: <code>s${r.site}@${r.info[0]}</code> ${esc(r.info[2])}`, `站点 = (字 & ${2 ** s.id_bits - 1}) − 1 = ${(r.w[0] & (2 ** s.id_bits - 1))} − 1 = <b>${r.site}</b>：<code>s${r.site}@${r.info[0]}</code> ${esc(r.info[2])}`),
        bi(`truncated clock c = word &gt;&gt; ${s.id_bits} = ${num(r.trunc)} (${32 - s.id_bits} bits, wraps every ${num(mod)} cycles)`, `截断时钟 c = 字 &gt;&gt; ${s.id_bits} = ${num(r.trunc)}（${32 - s.id_bits} 位，每 ${num(mod)} 个周期回绕）`),
        tNext != null
          ? bi(`unwrap from the ${r.k + 1 === s.n ? 'exit anchor clk_end' : 'next record'} t = ${num(tNext)}: clk = t − ((t − c) mod 2<sup>${32 - s.id_bits}</sup>) = <b>${num(r.full)}</b>, clk_start + ${num(r.full - H.clkS)}`, `从${r.k + 1 === s.n ? '出口锚点 clk_end' : '下一条记录'} t = ${num(tNext)} 回推：clk = t − ((t − c) mod 2<sup>${32 - s.id_bits}</sup>) = <b>${num(r.full)}</b>，即 clk_start + ${num(r.full - H.clkS)}`)
          : bi(`full clock clk_start + ${num(r.full - H.clkS)} (the next record is not on this page)`, `完整时钟 clk_start + ${num(r.full - H.clkS)}（下一条记录不在本页）`),
        bi(`ns = ⌊((clk − clk_start) × ${num(H.spanNs)} + ${num(Math.floor(H.spanClk / 2))}) / ${num(H.spanClk)}⌋ = <b>gt_start + ${num(r.ns)} ns</b>`, `ns = ⌊((clk − clk_start) × ${num(H.spanNs)} + ${num(Math.floor(H.spanClk / 2))}) / ${num(H.spanClk)}⌋ = <b>gt_start + ${num(r.ns)} ns</b>`)
      ];
      if (vHtml) steps.push(vHtml);
      steps.push(r.ok ? bi(`<span class="rx-ok">✓</span> equals Python's <code>decode_slot</code> for this record`, `<span class="rx-ok">✓</span> 与 Python <code>decode_slot</code> 对这条记录的结果一致`) : bi(`<span class="rx-bad">✗</span> differs from <code>decode_slot</code>`, `<span class="rx-bad">✗</span> 与 <code>decode_slot</code> 不一致`));
      stepsEl.innerHTML = steps.map((x) => `<li>${x}</li>`).join('');
